  const eventEnd = new Date(event.end_at).getTime();

  if (!Number.isFinite(slotStart)) return false;
  if (!Number.isFinite(slotEnd)) return false;
  if (!Number.isFinite(eventStart)) return false;
  if (!Number.isFinite(eventEnd)) return false;

  return slotStart < eventEnd && slotEnd > eventStart;
}

const availableSlots = candidateSlots
  .filter(slot => !busyEvents.some(event => overlaps(slot, event)))
  .slice(0, maxSlots);

return [{
  success: true,
  lead_id: base.lead_id,
  calendar_id: base.calendar_id,
  service_interest: base.service_interest,
  vehicle_type: base.vehicle_type,
  district: base.district,
  duration_minutes: base.duration_minutes,
  days_ahead: base.days_ahead,
  start_offset_days: base.start_offset_days,
  max_slots: base.max_slots,
  availability_window: base.availability_window,
  availability_label: base.availability_label,
  slots: availableSlots,
  busy_events: busyEvents,
  busy_events_db_count: dbBusyEvents.length,
  busy_events_calendar_count: calendarBusyEvents.length,
  checked_at: new Date().toISOString()
}];

const original = $("generate_candidate_slots").first().json;
const auth = $json || {};

// Si la seleccion de personal asigno un calendario propio a esa persona
// (agent_staff.calendar_id), ese manda por sobre el calendario por defecto
// del agente que devuelve get_valid_calendar_token. Cuando el negocio opera
// con un solo calendario compartido este campo llega vacio o como "primary"
// y se sigue usando el del agente, igual que siempre.
const staffCalendarId =
  original.calendar_id && original.calendar_id !== "primary"
    ? original.calendar_id
    : null;

return [{
  json: {
    ...original,
    oauth_connected: auth.connected === true,
    oauth_access_token: auth.access_token || null,
    oauth_calendar_id: staffCalendarId || auth.calendar_id || null
  }
}];

const response = $json || {};
const items = Array.isArray(response.items) ? response.items : [];

if (items.length === 0) {
  // Sin esto, n8n deja de propagar la ejecucion cuando el calendario
  // dedicado esta vacio (0 items de salida = nodos siguientes no corren).
  return [{ json: { id: null, summary: null, start: null, end: null, status: null } }];
}

return items.map((event) => ({
  json: {
    id: event.id || null,
    summary: event.summary || null,
    start: event.start || null,
    end: event.end || null,
    status: event.status || null
  }
}));

